"""Analyze saved confirmation episodes; no simulations or tuning."""
import pathlib,json,csv,itertools,hashlib,math
import numpy as np
from scipy.stats import beta,binomtest
D=pathlib.Path(__file__).resolve().parent;M=json.loads((D/'manifest.json').read_text())
def load():
 out={}
 for p in (D/'validation').glob('*.json'):
  r=json.loads(p.read_text())
  if 'candidate' in r:out.setdefault(r['candidate'],[]).append(r)
 for rs in out.values():rs.sort(key=lambda r:r['seed'])
 return out
def export(p,rs):
 if rs:
  with p.open('w') as f:w=csv.DictWriter(f,fieldnames=list(rs[0]));w.writeheader();w.writerows(rs)
def ci(k,n,q=.025):return (float(beta.ppf(q,k,n-k+1)) if k else 0.,float(beta.ppf(1-q,k+1,n-k)) if k<n else 1.)
def boot(v,rng):
 if not len(v):return [None,None]
 v=np.asarray(v);m=np.concatenate([v[rng.integers(0,len(v),(1000,len(v)))].mean(1) for _ in range(10)])
 return np.quantile(m,[.025,.975]).tolist()
def main():
 x=load();rows=[];eps=[];pp=[];rng=np.random.default_rng(20261116)
 for name,rs in x.items():
  h=M['candidates'][name]['historical'];n=len(rs);k=sum(r['success'] for r in rs);tt=[r['race_time_s'] for r in rs if r['success']];ds=np.concatenate([r['durations_ms'] for r in rs]);lo,hi=ci(k,n)
  rows.append(dict(candidate=name,historical_configuration_id=M['candidates'][name]['historical_id'],n=n,finishes=k,completion=k/n,completion_ci_lower=lo,completion_ci_upper=hi,mean_success_time_s=float(np.mean(tt)) if tt else None,p90_success_time_s=float(np.quantile(tt,.9)) if tt else None,p90_provisional=len(tt)<30,penalized_mean_time_s=float(np.mean([r['penalized_time_s'] for r in rs])),failed_solver_ticks=sum(r['failed_solve_ticks'] for r in rs),fallback_ticks=sum(r['fallback_ticks'] for r in rs),affected_episodes=sum(bool(r['fallback_ticks'] or r['failed_solve_ticks']) for r in rs),controller_calls=len(ds),compute_mean_ms=float(np.mean(ds)),compute_p99_ms=float(np.quantile(ds,.99)),calls_over_20ms=int(sum(ds>20)),historical_n=h['episodes'],historical_finishes=h['finishes'],historical_mean_success_time_s=h['mean_success_time_s'],environment='common frozen official-core simulator; exact paired states verified',status='independent postselection confirmation; separate from historical screening'))
  for r in rs:eps.append({a:r[a] for a in ['candidate','seed','initial_state_sha256','success','steps','race_time_s','official_time_s','penalized_time_s','failed_solve_ticks','fallback_ticks','timestamp']})
 for a,b in itertools.combinations(sorted(x),2):
  aa={r['seed']:r for r in x[a]};bb={r['seed']:r for r in x[b]};seeds=sorted(aa.keys()&bb.keys());n=len(seeds)
  assert all(aa[s]['initial_state_sha256']==bb[s]['initial_state_sha256'] for s in seeds)
  gain=sum(bb[s]['success'] and not aa[s]['success'] for s in seeds);loss=sum(aa[s]['success'] and not bb[s]['success'] for s in seeds);l1,u1=ci(gain,n,.0125);l2,u2=ci(loss,n,.0125)
  pt=[bb[s]['penalized_time_s']-aa[s]['penalized_time_s'] for s in seeds];dt=[bb[s]['race_time_s']-aa[s]['race_time_s'] for s in seeds if aa[s]['success'] and bb[s]['success']];pl,pu=boot(pt,rng);tl,tu=boot(dt,rng)
  pp.append(dict(reference=a,candidate=b,n=n,rescues=gain,regressions=loss,completion_difference=(gain-loss)/n,completion_ci_lower=l1-u2,completion_ci_upper=u1-l2,mcnemar_exact_p=binomtest(gain,gain+loss).pvalue if gain+loss else 1.,penalized_delta_s=float(np.mean(pt)),penalized_ci_lower=pl,penalized_ci_upper=pu,shared_success_n=len(dt),shared_success_mean_delta_s=float(np.mean(dt)) if dt else None,shared_success_ci_lower=tl,shared_success_ci_upper=tu))
 last=0
 for j,i in enumerate(sorted(range(len(pp)),key=lambda i:pp[i]['mcnemar_exact_p'])):last=max(last,min(1,pp[i]['mcnemar_exact_p']*(len(pp)-j)));pp[i]['mcnemar_holm_p']=last
 rows.sort(key=lambda r:(-r['completion'],r['penalized_mean_time_s'],r['failed_solver_ticks']))
 export(D/'metrics.csv',rows);export(D/'episodes.csv',eps);export(D/'paired_comparisons.csv',pp)
 print(json.dumps(rows,indent=2))
 if len(rows)!=6 or any(r['n']!=100 for r in rows):return
 text=['# Speed-threshold configurations: 100 fresh episodes each','', 'All six configurations received 100 new matched episodes, selected before testing because their table cohorts had fewer than 100 episodes and observed completion at least 40%. Duplicate table appearances were tested once. No tuning or outcome-dependent stopping. New rates below stand separately from historical screening.','', '| Configuration | New completion (exact 95% CI) | New successful mean / p90 | 30 s penalized mean | Failed / fallback ticks | Original screening | Original successful mean |','|---|---|---|---|---|---|---|']
 for r in rows:text.append(f"| {r['candidate']} | {r['finishes']}/100 ({100*r['completion']:.1f}%; {100*r['completion_ci_lower']:.1f}–{100*r['completion_ci_upper']:.1f}%) | {r['mean_success_time_s']:.3f} / {r['p90_success_time_s']:.3f} s | {r['penalized_mean_time_s']:.3f} s | {r['failed_solver_ticks']} / {r['fallback_ticks']} | {r['historical_finishes']}/{r['historical_n']} | {float(r['historical_mean_success_time_s']):.3f} s |")
 text+=['','## Methods and provenance','', 'Fresh seed lists, full settings and source hashes were frozen before measured validation. The same physical environment/config/source pins apply to all six controllers; each paired reset is verified using a full EnvData hash and saved NumPy arrays. Source packages and the V3 naming-only adapter were recovered from the retained records. V3 soft constraints and progress-bound repair are preserved. speed33_combined uses its original soft-attitude formulation; drag_10 remains hard-bound. No official physics or active project configuration was changed.','', 'Broad/prediction build caches are per configuration, with path-length bounds refreshed. V3 retains unique fresh builds and its embedded progress-bound restoration. Technical smoke and cached/rebuilt action comparisons are excluded from reported performance. Every compute_control call is timed; construction, callbacks, simulation and diagnostics are outside that boundary. Candidate order rotates across seeds; candidates run serially. Ordinary background desktop load remains a timing limitation. Timing summaries are in metrics.csv.','', 'Race times use completed steps / 50 Hz, matching the retained assessment convention. Original zero-based official times, 0.02 s lower, are separately retained. Average times condition on successful completion. Failed races score 30 s. Explicit hover fallback and nonzero solver status are recorded separately; absent events are observed zeros, not missing telemetry.','', 'Individual completion intervals are exact Clopper–Pearson 95%. All 15 paired comparisons are in paired_comparisons.csv: exact McNemar tests with Holm correction within this confirmation, conservative paired completion intervals, and 10,000 deterministic paired bootstrap intervals for penalized time and joint-success time. Time intervals are pointwise. A small successful-time gain does not compensate for a large completion loss.','', 'Historical implementation/environment identities and source evidence are retained in manifest.json and source_verification.json. V3 evidence listed both installed CasADi solver-library copies and acados libraries; the original runtime used LD_LIBRARY_PATH=acados/lib. This run pins that same acados library path and verifies loaded runtime maps. Historical screening and new validation are not pooled. The known MuJoCo 3.10 initialization collision-sentinel warning is retained without installing the historical modified-core contact fix.','','', '## Reproduction','', 'From the repository root:','```bash','export LD_LIBRARY_PATH="$PWD/acados/lib${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"','.pixi/envs/default/bin/python docs/control/mpcc_speed_confirmation_20261116_v1/run.py --stage validation --cache','.pixi/envs/default/bin/python docs/control/mpcc_speed_confirmation_20261116_v1/analyze.py','.pixi/envs/default/bin/python docs/control/mpcc_speed_confirmation_20261116_v1/audit.py','```','Completed episode files are skipped on resume; source, settings and runner fingerprints must match. For an independent rerun, copy the preparation/source/scripts to a new sibling directory and start with empty smoke/validation directories; retain the fixed seeds when reproducing this exact dataset.']
 text+=['','## Interpretation','', 'The top three observed completion rates are vertical_taper_higher 68/100, S28_D20_P9 67/100 and V3 reference_speed_2p8 66/100. No pair among these establishes a completion advantage after Holm correction (all adjusted p=1); that does not prove equivalence. The V3 configuration is the most promising of these tested candidates for a sub-5-second successful average: 4.966 s, with zero observed failed solver/fallback ticks. On jointly successful seeds it was 0.207 s faster than S28_D20_P9 and 0.356 s faster than vertical_taper_higher.','', 'drag_10 fell from 18/30 (60%) screening completion to 45/100, with 76 failed/fallback ticks across 13 episodes. speed33_combined remained at 40% completion, but its successful mean increased to 4.604 s, missing the former under-4.6-second cutoff. depth_0p35 averaged 4.819 s, missing its former under-4.8-second cutoff. Historical screening and this independent confirmation are shown separately; observed changes alone are not causal evidence of an implementation or environment effect.','', 'The updated 0.1-second threshold table uses the new results for these six configurations and retains other existing evidence. Newly appearing screening leaders remain unconfirmed; no additional simulations were run for them. See updated_threshold_table.md and updated_threshold_table.csv.']
 (D/'report.md').write_text('\n'.join(text)+'\n')
if __name__=='__main__':main()
